INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Softwareproblem im Anwendersupport durch einen Programmabsturz verursacht werden?', 2, '[{"text": "Ja", "correct": true, "because": "Abstürze sind typische Softwarefehler"}, {"text": "Nein", "correct": false, "because": "Abstürze gehören dazu"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Softwareproblem immer durch eine Neuinstallation behoben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Oft reicht ein Update oder Neustart"}, {"text": "Ja", "correct": false, "because": "Andere Lösungen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine langsame Programmreaktion ein technisches Softwareproblem?', 2, '[{"text": "Ja", "correct": true, "because": "Leistungseinbußen sind Softwareprobleme"}, {"text": "Nein", "correct": false, "because": "Langsamkeit fällt darunter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Softwareproblem durch fehlende Updates entstehen?', 2, '[{"text": "Ja", "correct": true, "because": "Updates beheben Fehler"}, {"text": "Nein", "correct": false, "because": "Fehlende Updates sind Ursache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Softwareprobleme im Anwendersupport immer durch Viren verursacht?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Ursachen wie Bugs möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Viren"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Softwareproblem führt dazu, dass ein Programm nicht startet?', 2, '[{"text": "Fehlende Dateien", "correct": true, "because": "Programm benötigt alle Dateien"}, {"text": "Langsame Festplatte", "correct": false, "because": "Hardwareproblem"}, {"text": "Defekter Monitor", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symptom deutet auf ein Softwareproblem im Anwendersupport hin?', 3, '[{"text": "Fehlermeldung", "correct": true, "because": "Typisch für Softwarefehler"}, {"text": "Kein Ton", "correct": false, "because": "Kann Hardware sein"}, {"text": "Überhitzung", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der erste Schritt bei einem Softwareproblem im Anwendersupport?', 2, '[{"text": "Neustart des Programms", "correct": true, "because": "Löst viele Probleme"}, {"text": "Hardware austauschen", "correct": false, "because": "Hardwarelösung"}, {"text": "Kabel prüfen", "correct": false, "because": "Hardwarebezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Softwarekomponente ist oft für Kompatibilitätsprobleme verantwortlich?', 2, '[{"text": "Betriebssystem", "correct": true, "because": "Versionen müssen passen"}, {"text": "Drucker", "correct": false, "because": "Hardware"}, {"text": "Lüfter", "correct": false, "because": "Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Diagnose eines Softwareproblems?', 2, '[{"text": "Ereignisanzeige", "correct": true, "because": "Zeigt Fehlerprotokolle"}, {"text": "Multimeter", "correct": false, "because": "Hardwaretool"}, {"text": "Schraubenzieher", "correct": false, "because": "Hardwarewerkzeug"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Softwareprobleme treten im Anwendersupport häufig auf?', 3, '[{"text": "Programmabsturz", "correct": true, "because": "Häufiger Fehler"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Versionskonflikte"}, {"text": "Fehlende Updates", "correct": true, "because": "Fehleranfälligkeit"}, {"text": "Defekte Grafikkarte", "correct": false, "because": "Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symptome deuten auf Softwareprobleme im Anwendersupport hin?', 4, '[{"text": "Langsame Reaktion", "correct": true, "because": "Softwareleistung"}, {"text": "Fehlermeldungen", "correct": true, "because": "Programmfehler"}, {"text": "Abstürze", "correct": true, "because": "Softwareinstabilität"}, {"text": "Klickgeräusche", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen helfen bei Softwareproblemen im Anwendersupport?', 3, '[{"text": "Neustart", "correct": true, "because": "Löst viele Fehler"}, {"text": "Update installieren", "correct": true, "because": "Behebt Bugs"}, {"text": "Neuinstallation", "correct": true, "because": "Wiederherstellung"}, {"text": "Staub entfernen", "correct": false, "because": "Hardwarelösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursachen können Softwareprobleme im Anwendersupport haben?', 4, '[{"text": "Programmierfehler", "correct": true, "because": "Bugs in Software"}, {"text": "Fehlkonfiguration", "correct": true, "because": "Falsche Einstellungen"}, {"text": "Virenbefall", "correct": true, "because": "Schadsoftware"}, {"text": "Überhitzung", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Diagnosemethoden werden bei Softwareproblemen im Anwendersupport genutzt?', 3, '[{"text": "Fehlerprotokolle prüfen", "correct": true, "because": "Zeigt Problemursache"}, {"text": "Abgesicherter Modus", "correct": true, "because": "Isoliert Fehler"}, {"text": "Antivirus-Scan", "correct": true, "because": "Erkennt Schadsoftware"}, {"text": "Temperaturmessung", "correct": false, "because": "Hardwareprüfung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Softwareproblem kann durch einen Virus entstehen. b) Softwareprobleme betreffen nie das Betriebssystem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Virus ja, Betriebssystem auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Programmabsturz ist ein Softwareproblem. b) Softwareprobleme lassen sich nie durch einen Neustart lösen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Absturz ja, Neustart oft hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlermeldungen sind ein Hinweis auf Softwareprobleme. b) Ein Softwareproblem kann nicht durch Benutzerfehler entstehen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlermeldungen ja, Benutzerfehler möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Update kann Softwareprobleme beheben. b) Softwareprobleme sind immer sofort sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Update ja, Sichtbarkeit nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kompatibilitätsprobleme sind Softwareprobleme. b) Ein Softwareproblem erfordert immer eine Neuinstallation des PCs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kompatibilität ja, Neuinstallation nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

